{
  "fill": [
    {
      "prompt": "有些 ___ 請求瀏覽器不敢直接送。",
      "answers": [
        ["跨來源"]
      ]
    },
    {
      "prompt": "改變伺服器狀態的方法,或帶了自訂標頭的請求,瀏覽器會先發一個 ___,詢問伺服器是否願意接受。",
      "answers": [
        ["預檢請求", "詢問請求"]
      ]
    },
    {
      "prompt": "伺服器同意後,瀏覽器才送出真正的請求;而且預檢的結果可以被 ___ 一段時間,避免每次都多一趟 ___。",
      "answers": [
        ["快取", "快取起來"],
        ["往返", "網路往返"]
      ]
    }
  ],
  "apply": [
    {
      "prompt": "你要從一個不同來源送出會改變伺服器狀態的請求。請說明瀏覽器會如何處理，以及這樣做的目的。",
      "rubric": [
        "回答指出瀏覽器會先發出預檢或詢問請求",
        "回答指出伺服器同意後瀏覽器才會送出真正的請求",
        "回答指出這個機制是為了保護原本未預期收到跨來源寫入請求的舊系統"
      ]
    }
  ]
}
